// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.DesignRequest.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(designrequest.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *DesignRequestUpsertBulk) UpdateNewValues() *DesignRequestUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(designrequest.FieldID)
			}
			if _, exists := b.mutation.ShopID(); exists {
				s.SetIgnore(designrequest.FieldShopID)
			}
			if _, exists := b.mutation.Site(); exists {
				s.SetIgnore(designrequest.FieldSite)
			}
			if _, exists := b.mutation.Kind(); exists {
				s.SetIgnore(designrequest.FieldKind)
			}
			if _, exists := b.mutation.RequestedByUserID(); exists {
				s.SetIgnore(designrequest.FieldRequestedByUserID)
			}
			if _, exists := b.mutation.PromptSha256(); exists {
				s.SetIgnore(designrequest.FieldPromptSha256)
			}
			if _, exists := b.mutation.BaseSha(); exists {
				s.SetIgnore(designrequest.FieldBaseSha)
			}
			if _, exists := b.mutation.RestoresRequestID(); exists {
				s.SetIgnore(designrequest.FieldRestoresRequestID)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(designrequest.FieldCreatedAt)
			}
		}
	}))
	return u
}

